window.__EPHONE_HTML_PARTS[14] = "<!-- 天气设置 (仅单聊显示) - UI 优化版 -->\r\n<div class=\"settings-section\" id=\"weather-settings-section\" style=\"display: none;\">\r\n    <!-- 开关行 -->\r\n    <div class=\"settings-item\">\r\n        <label>启用实时天气同步</label>\r\n        <label class=\"toggle-switch\">\r\n            <input type=\"checkbox\" id=\"enable-weather-switch\">\r\n            <span class=\"slider\"></span>\r\n        </label>\r\n    </div>\r\n    \r\n    <!-- 详情配置区域 (由JS控制显示/隐藏) -->\r\n    <div id=\"weather-config-container\" style=\"display: none;\">\r\n        \r\n        <!-- 我的位置 -->\r\n        <div class=\"settings-item-block\">\r\n            <label style=\"font-weight: 500;\">我的位置 (User)</label>\r\n            <div class=\"weather-input-group\">\r\n                <input type=\"text\" id=\"user-virtual-city\" placeholder=\"虚拟名 (如: 龙城)\" class=\"weather-input\">\r\n                <input type=\"text\" id=\"user-real-city-search\" placeholder=\"真实城市 (拼音/英文)\" class=\"weather-input\">\r\n                <button id=\"user-city-search-btn\" class=\"settings-mini-btn\" style=\"margin-left: 0;\">搜索</button>\r\n            </div>\r\n            <!-- 隐藏域 -->\r\n            <input type=\"hidden\" id=\"user-city-lat\">\r\n            <input type=\"hidden\" id=\"user-city-lon\">\r\n            <!-- 结果展示 -->\r\n            <div id=\"user-city-result\" class=\"weather-result-text\">未设置映射</div>\r\n        </div>\r\n\r\n        <!-- 对方位置 -->\r\n        <div class=\"settings-item-block\" style=\"border-bottom: none;\">\r\n            <label style=\"font-weight: 500;\">对方位置 (Char)</label>\r\n            <div class=\"weather-input-group\">\r\n                <input type=\"text\" id=\"char-virtual-city\" placeholder=\"虚拟名 (如: 哥谭)\" class=\"weather-input\">\r\n                <input type=\"text\" id=\"char-real-city-search\" placeholder=\"真实城市 (拼音/英文)\" class=\"weather-input\">\r\n                <button id=\"char-city-search-btn\" class=\"settings-mini-btn\" style=\"margin-left: 0;\">搜索</button>\r\n            </div>\r\n            <!-- 隐藏域 -->\r\n            <input type=\"hidden\" id=\"char-city-lat\">\r\n            <input type=\"hidden\" id=\"char-city-lon\">\r\n            <!-- 结果展示 -->\r\n            <div id=\"char-city-result\" class=\"weather-result-text\">未设置映射</div>\r\n        </div>\r\n\r\n    </div>\r\n</div>\r\n\r\n        <!-- 视频通话优化设置 -->\r\n        <div class=\"settings-section\" id=\"video-call-optimization-section\">\r\n            <!-- 开关行 -->\r\n            <div class=\"settings-item\">\r\n                <label>视频通话优化</label>\r\n                <label class=\"toggle-switch\">\r\n                    <input type=\"checkbox\" id=\"enable-video-optimization-switch\">\r\n                    <span class=\"slider\"></span>\r\n                </label>\r\n            </div>\r\n            \r\n            <!-- 详情配置区域 (由JS控制显示/隐藏) -->\r\n            <div id=\"video-optimization-config-container\" style=\"display: none;\">\r\n                \r\n                <!-- 对方视频图片 -->\r\n                <div class=\"settings-item-block\">\r\n                    <label style=\"font-weight: 500;\">对方视频画面</label>\r\n                    <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 8px;\">\r\n                        <img id=\"remote-video-preview\" src=\"\" \r\n                             style=\"width: 80px; height: 80px; border-radius: 8px; object-fit: cover; border: 2px solid #ddd; display: none;\">\r\n                        <div id=\"remote-video-placeholder\" style=\"width: 80px; height: 80px; border-radius: 8px; background: #f0f0f0; display: flex; align-items: center; justify-content: center; font-size: 12px; color: #999;\">未设置</div>\r\n                    </div>\r\n                    <div style=\"display: flex; gap: 8px; margin-top: 10px;\">\r\n                        <button class=\"settings-mini-btn\" onclick=\"document.getElementById('remote-video-input').click()\">本地上传</button>\r\n                        <button class=\"settings-mini-btn\" id=\"remote-video-url-btn\">URL上传</button>\r\n                        <button class=\"settings-mini-btn\" id=\"remote-video-reset-btn\" style=\"background: #ff3b30; color: white;\">重置</button>\r\n                        <input type=\"file\" id=\"remote-video-input\" accept=\"image/*\" hidden>\r\n                    </div>\r\n                    <input type=\"text\" id=\"remote-video-url-input\" placeholder=\"或输入图片URL\" \r\n                           style=\"width: 100%; padding: 8px; margin-top: 8px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\r\n                </div>\r\n\r\n                <!-- 我方视频图片 -->\r\n                <div class=\"settings-item-block\" style=\"border-bottom: none;\">\r\n                    <label style=\"font-weight: 500;\">我方视频画面</label>\r\n                    <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 8px;\">\r\n                        <img id=\"local-video-preview\" src=\"\" \r\n                             style=\"width: 80px; height: 80px; border-radius: 8px; object-fit: cover; border: 2px solid #ddd; display: none;\">\r\n                        <div id=\"local-video-placeholder\" style=\"width: 80px; height: 80px; border-radius: 8px; background: #f0f0f0; display: flex; align-items: center; justify-content: center; font-size: 12px; color: #999;\">未设置</div>\r\n                    </div>\r\n                    <div style=\"display: flex; gap: 8px; margin-top: 10px;\">\r\n                        <button class=\"settings-mini-btn\" onclick=\"document.getElementById('local-video-input').click()\">本地上传</button>\r\n                        <button class=\"settings-mini-btn\" id=\"local-video-url-btn\">URL上传</button>\r\n                        <button class=\"settings-mini-btn\" id=\"local-video-reset-btn\" style=\"background: #ff3b30; color: white;\">重置</button>\r\n                        <input type=\"file\" id=\"local-video-input\" accept=\"image/*\" hidden>\r\n                    </div>\r\n                    <input type=\"text\" id=\"local-video-url-input\" placeholder=\"或输入图片URL\" \r\n                           style=\"width: 100%; padding: 8px; margin-top: 8px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\r\n                </div>\r\n\r\n                <!-- 真实摄像头设置 -->\r\n                <div class=\"settings-item-block\" style=\"border-bottom: none; padding-top: 15px; border-top: 1px solid #e0e0e0; margin-top: 15px;\">\r\n                    <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;\">\r\n                        <label style=\"font-weight: 500;\">使用真实摄像头</label>\r\n                        <label class=\"toggle-switch\">\r\n                            <input type=\"checkbox\" id=\"enable-real-camera-switch\">\r\n                            <span class=\"slider\"></span>\r\n                        </label>\r\n                    </div>\r\n                    <div style=\"font-size: 12px; color: #666; margin-bottom: 10px;\">\r\n                        启用后，我方画面将使用设备摄像头，AI可以真正\"看到\"你\r\n                    </div>\r\n                    \r\n                    <!-- 截图间隔设置 -->\r\n                    <div id=\"camera-interval-setting\" style=\"display: none;\">\r\n                        <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 10px;\">\r\n                            <label style=\"font-size: 13px; white-space: nowrap;\">截图间隔</label>\r\n                            <input type=\"number\" id=\"camera-capture-interval\" \r\n                                   min=\"1\" max=\"60\" value=\"5\" \r\n                                   style=\"width: 60px; padding: 6px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\r\n                            <span style=\"font-size: 13px; color: #666;\">秒</span>\r\n                        </div>\r\n                        <div style=\"font-size: 11px; color: #999; margin-top: 5px;\">\r\n                            定时截取摄像头画面发送给AI，默认5秒\r\n                        </div>\r\n                        \r\n                        <!-- 使用后置摄像头开关 -->\r\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 12px;\">\r\n                            <label style=\"font-size: 13px;\">使用后置摄像头</label>\r\n                            <label class=\"toggle-switch\">\r\n                                <input type=\"checkbox\" id=\"enable-rear-camera-switch\">\r\n                                <span class=\"slider\"></span>\r\n                            </label>\r\n                        </div>\r\n                        <div style=\"font-size: 11px; color: #999; margin-top: 5px;\">\r\n                            开启后将切换为后置摄像头（仅移动设备有效）\r\n                        </div>\r\n\r\n                        <!-- 摄像头状态 -->\r\n                        <div id=\"camera-status\" style=\"margin-top: 10px; padding: 8px; background: #f9f9f9; border-radius: 6px; font-size: 12px; display: none;\">\r\n                            <div style=\"display: flex; align-items: center; gap: 5px;\">\r\n                                <span id=\"camera-status-icon\" style=\"width: 8px; height: 8px; border-radius: 50%; background: #ccc;\"></span>\r\n                                <span id=\"camera-status-text\" style=\"color: #666;\">摄像头未激活</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                    \r\n                    <!-- 仅读取对话开关 -->\r\n                    <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid #e0e0e0;\">\r\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\r\n                            <label style=\"font-weight: 500; font-size: 13px;\">仅读取对话内容</label>\r\n                            <label class=\"toggle-switch\" style=\"transform: scale(0.9);\">\r\n                                <input type=\"checkbox\" id=\"tts-dialogue-only-switch\">\r\n                                <span class=\"slider\"></span>\r\n                            </label>\r\n                        </div>\r\n                        <div style=\"font-size: 11px; color: #666; line-height: 1.5;\">\r\n                            启用后，语音播报只读取引号内的对话，不读取动作描写等旁白内容\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- 旁白对话穿插模式 -->\r\n                    <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid #e0e0e0;\">\r\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\r\n                            <label style=\"font-weight: 500; font-size: 13px;\">旁白与对话穿插</label>\r\n                            <label class=\"toggle-switch\" style=\"transform: scale(0.9);\">\r\n                                <input type=\"checkbox\" id=\"video-interleaved-mode-switch\">\r\n                                <span class=\"slider\"></span>\r\n                            </label>\r\n                        </div>\r\n                        <div style=\"font-size: 11px; color: #666; line-height: 1.5;\">\r\n                            启用后，旁白和对话按自然顺序穿插显示，而非旁白合并在前、对话在后\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n\r\n            </div>\r\n        </div>\r\n\r\n        <!-- 记忆库区域 -->\r\n        <div class=\"settings-section\" id=\"memory-archive-section\">\r\n            <div class=\"settings-item\">\r\n                <label style=\"font-weight: 600; font-size: 16px;\">记忆库</label>\r\n            </div>\r\n            \r\n            <div id=\"memory-archive-container\" style=\"padding: 0 15px;\">\r\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\r\n                    保存当前聊天的所有记录和设置（人设、头像、长期记忆、语音、预设等），方便多路线管理\r\n                </div>\r\n                \r\n                <button id=\"save-memory-archive-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\r\n                    保存当前状态\r\n                </button>\r\n                \r\n                <div id=\"memory-archive-list\" style=\"display: flex; flex-direction: column; gap: 10px;\">\r\n                    <!-- 存档列表将动态生成 -->\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- API调用历史区域 -->\r\n        <div class=\"settings-section\" id=\"api-history-section\">\r\n            <div class=\"settings-item\">\r\n                <label style=\"font-weight: 600; font-size: 16px;\">API调用历史</label>\r\n            </div>\r\n            \r\n            <div style=\"padding: 0 15px;\">\r\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\r\n                    查看每次发送给AI的原始提示词、调用信息和返回的原始数据\r\n                </div>\r\n                \r\n                <button id=\"view-api-history-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\r\n                    查看返回的提示词\r\n                </button>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- 消息导航区域 -->\r\n        <div class=\"settings-section\" id=\"message-navigation-section\">\r\n            <div class=\"settings-item\">\r\n                <label style=\"font-weight: 600; font-size: 16px;\">消息导航</label>\r\n            </div>\r\n            \r\n            <div style=\"padding: 0 15px;\">\r\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\r\n                    快速跳转到聊天记录的开头或结尾。当聊天记录较多时，可能会有轻微延迟。\r\n                </div>\r\n                \r\n                <button id=\"scroll-to-first-message-btn\" class=\"form-button\" style=\"margin-bottom: 10px;\">\r\n                    回到第一条消息\r\n                </button>\r\n                \r\n                <button id=\"scroll-to-last-message-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\r\n                    回到最后一条消息\r\n                </button>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- 第四组：高级功能 (TTS, NAI, 线下模式) -->\r\n        <div class=\"settings-section\">\r\n             <!-- 时间戳显示格式 -->\r\n             <div class=\"settings-item\">\r\n                 <div>\r\n                     <div style=\"font-weight: 500;\">显示秒数</div>\r\n                     <div style=\"font-size: 12px; color: var(--text-secondary);\">开启后，此聊天的时间戳将显示为\"时:分:秒\"格式（覆盖全局设置）</div>\r\n                 </div>\r\n                 <label class=\"toggle-switch\">\r\n                     <input type=\"checkbox\" id=\"chat-show-seconds-switch\">\r\n                     <span class=\"slider\"></span>\r\n                 </label>\r\n             </div>\r\n             \r\n             <!-- 语音 -->\r\n             <div class=\"settings-item\" id=\"tts-enable-group\">\r\n                 <label>启用语音合成 (TTS)</label>\r\n                 <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"enable-tts-switch\"> <span class=\"slider\"></span> </label>\r\n             </div>\r\n             <div class=\"settings-item\" id=\"ai-voice-id-group\">\r\n                 <label>语音 ID</label>\r\n                 <div class=\"settings-right\">\r\n                    <input type=\"text\" id=\"ai-voice-id-input\" placeholder=\"minimax voice_id\">\r\n                 </div>\r\n             </div>\r\n             <div class=\"settings-item\" id=\"ai-voice-lang-group\">\r\n                <label>语音语言/方言</label>\r\n                <div class=\"settings-right\">\r\n                  <select id=\"ai-voice-lang-select\" class=\"settings-select\" style=\"width: 100%; text-align: right;\">\r\n                    <option value=\"\"> 自动识别 (Auto)</option>\r\n                    <hr disabled>\r\n                    <option value=\"zh-CN\">国语/普通话 (Chinese)</option>\r\n                    <option value=\"zh-HK\">粤语/广东话 (Cantonese)</option>\r\n                    <option value=\"en-US\">英语 (English)</option>\r\n                    <option value=\"ja-JP\">日语 (Japanese)</option>\r\n                    <option value=\"ko-KR\">韩语 (Korean)</option>\r\n                    <hr disabled>\r\n                    <option value=\"de-DE\">德语 (German)</option>\r\n                    <option value=\"fr-FR\">法语 (French)</option>\r\n                    <option value=\"es-ES\">西班牙语 (Spanish)</option>\r\n                    <option value=\"it-IT\">意大利语 (Italian)</option>\r\n                    <option value=\"ru-RU\">俄语 (Russian)</option>\r\n                    <option value=\"pt-BR\">葡萄牙语 (Portuguese)</option>\r\n                    <option value=\"nl-NL\">荷兰语 (Dutch)</option>\r\n                    <option value=\"pl-PL\">波兰语 (Polish)</option>\r\n                    <option value=\"sv-SE\">瑞典语 (Swedish)</option>\r\n                    <hr disabled>\r\n                    <option value=\"tr-TR\">土耳其语 (Turkish)</option>\r\n                    <option value=\"id-ID\">印尼语 (Indonesian)</option>\r\n                    <option value=\"ms-MY\">马来语 (Malay)</option>\r\n                    <option value=\"vi-VN\">越南语 (Vietnamese)</option>\r\n                    <option value=\"th-TH\">泰语 (Thai)</option>\r\n                    <option value=\"hi-IN\">印地语 (Hindi)</option>\r\n                   <option value=\"ar-SA\">阿拉伯语 (Arabic)</option>\r\n                 </select>\r\n               </div>\r\n            </div>\r\n             <div class=\"settings-item\" id=\"ai-voice-speed-group\">\r\n               <label>语音速度</label>\r\n               <div class=\"settings-right\">\r\n                 <input type=\"number\" id=\"ai-voice-speed-input\" min=\"0.5\" max=\"2.0\" step=\"0.1\" value=\"1.0\" style=\"width: 80px; text-align: right; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--secondary-bg); color: var(--text-color);\">\r\n                 <span style=\"margin-left: 5px; color: var(--text-secondary); font-size: 12px;\">x</span>\r\n               </div>\r\n             </div>\r\n             <div class=\"voice-input-settings\" id=\"voice-input-settings\">\r\n               <div class=\"settings-item\" id=\"real-voice-enable-group\">\r\n                 <div style=\"flex: 1; padding-right: 10px;\">\r\n                   <label style=\"margin-bottom: 2px;\">启用真实语音</label>\r\n                   <div class=\"settings-desc\">保留原有模拟语音，并允许录制、发送和播放你的原声</div>\r\n                 </div>\r\n                 <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"enable-real-voice-switch\"><span class=\"slider\"></span></label>\r\n               </div>\r\n               <div id=\"real-voice-config-container\" style=\"display: none;\">\r\n                 <div class=\"voice-settings-note\">安卓/iOS 建议选“自动”或“后台转文字”；Gemini 音频理解使用当前 Gemini API 配置，Claude/DeepSeek 请走转写接口。</div>\r\n                 <div class=\"settings-item voice-config-row\">\r\n                   <label for=\"real-voice-operation-select\">聊天录音方式</label>\r\n                   <select id=\"real-voice-operation-select\" class=\"settings-select voice-settings-select\">\r\n                     <option value=\"tap\">点击开始/结束</option>\r\n                     <option value=\"hold\">按住说话</option>\r\n                   </select>\r\n                 </div>\r\n                 <div class=\"settings-item voice-config-row\">\r\n                   <label for=\"voice-understanding-mode-select\">角色理解方式</label>\r\n                   <select id=\"voice-understanding-mode-select\" class=\"settings-select voice-settings-select\">\r\n                     <option value=\"auto\">自动选择</option>\r\n                     <option value=\"transcription\">后台转文字</option>\r\n                     <option value=\"gemini\">Gemini 音频理解</option>\r\n                     <option value=\"browser\">浏览器识别（旧方式）</option>\r\n                     <option value=\"none\">仅发送原声</option>\r\n                   </select>\r\n                 </div>\r\n                 <div id=\"voice-transcription-settings\" class=\"voice-nested-settings\">\r\n                   <div class=\"settings-item voice-field-row\">\r\n                     <label for=\"voice-transcription-url-input\">转写接口</label>\r\n                     <input type=\"url\" id=\"voice-transcription-url-input\" class=\"voice-settings-input\" placeholder=\"OpenAI 兼容 /audio/transcriptions\">\r\n                   </div>\r\n                   <div class=\"settings-item voice-field-row\">\r\n                     <label for=\"voice-transcription-model-input\">转写模型</label>\r\n                     <input type=\"text\" id=\"voice-transcription-model-input\" class=\"voice-settings-input\" placeholder=\"whisper-1\">\r\n                   </div>\r\n                   <div class=\"settings-item voice-field-row\">\r\n                     <label for=\"voice-transcription-key-input\">转写密钥</label>\r\n                     <input type=\"password\" id=\"voice-transcription-key-input\" class=\"voice-settings-input\" autocomplete=\"off\" placeholder=\"留空时使用主 API Key\">\r\n                   </div>\r\n                 </div>\r\n                 <div class=\"settings-item voice-config-row\">\r\n                   <label for=\"voice-max-duration-select\">最长录音</label>\r\n                   <select id=\"voice-max-duration-select\" class=\"settings-select voice-settings-select\">\r\n                     <option value=\"30\">30 秒</option>\r\n                     <option value=\"60\">60 秒</option>\r\n                     <option value=\"120\">120 秒</option>\r\n                   </select>\r\n                 </div>\r\n                 <div class=\"settings-item\">\r\n                   <div style=\"flex: 1; padding-right: 10px;\">\r\n                     <label style=\"margin-bottom: 2px;\">发送前确认文字</label>\r\n                     <div class=\"settings-desc\">识别失败也不会丢失录音，可手动补充或直接发送原声</div>\r\n                   </div>\r\n                   <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"voice-confirm-transcript-switch\"><span class=\"slider\"></span></label>\r\n                 </div>\r\n                 <div class=\"voice-settings-title voice-call-settings-title\">语音电话输入</div>\r\n                 <div class=\"settings-item voice-config-row\">\r\n                   <label for=\"voice-call-input-mode-select\">我的说话方式</label>\r\n                   <select id=\"voice-call-input-mode-select\" class=\"settings-select voice-settings-select\">\r\n                     <option value=\"text\">文字输入（原方式）</option>\r\n                     <option value=\"hold\">按住说话</option>\r\n                     <option value=\"tap\">点击开始/结束</option>\r\n                   </select>\r\n                 </div>\r\n                 <div class=\"settings-item voice-config-row\">\r\n                   <label for=\"voice-call-understanding-select\">电话理解方式</label>\r\n                   <select id=\"voice-call-understanding-select\" class=\"settings-select voice-settings-select\">\r\n                     <option value=\"same\">跟随聊天设置</option>\r\n                     <option value=\"auto\">自动选择</option>\r\n                     <option value=\"transcription\">后台转文字</option>\r\n                     <option value=\"gemini\">Gemini 音频理解</option>\r\n                     <option value=\"browser\">浏览器识别（旧方式）</option>\r\n                     <option value=\"none\">仅记录原声</option>\r\n                   </select>\r\n                 </div>\r\n                 <div class=\"settings-item\">\r\n                   <div style=\"flex: 1; padding-right: 10px;\">\r\n                     <label style=\"margin-bottom: 2px;\">识别失败可补文字</label>\r\n                     <div class=\"settings-desc\">保留电话原有文字输入作为可恢复操作</div>\r\n                   </div>\r\n                   <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"voice-call-text-fallback-switch\"><span class=\"slider\"></span></label>\r\n                 </div>\r\n               </div>\r\n             </div>\r\n <div class=\"settings-item\" id=\"synth-music-group\">\r\n    <div>\r\n        <label>启用乐谱合成</label>\r\n        <div class=\"settings-desc\">允许角色发送乐谱并自动演奏</div>\r\n    </div>\r\n    <label class=\"toggle-switch\">\r\n        <input type=\"checkbox\" id=\"enable-synth-music-switch\">\r\n        <span class=\"slider\"></span>\r\n    </label>\r\n</div>\r\n<div class=\"settings-item\" id=\"narrator-mode-group\" style=\"display: flex; justify-content: space-between; align-items: center;\">\r\n    <div style=\"flex: 1; padding-right: 10px;\">\r\n        <label style=\"margin-bottom: 2px;\">启用旁白模式</label>\r\n        <div class=\"settings-desc\">AI每轮回复都会附带环境或心理描写 (灰色系统字)</div>\r\n    </div>\r\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \r\n        <input type=\"checkbox\" id=\"narrator-mode-toggle\">\r\n        <span class=\"slider\"></span>\r\n    </label>\r\n</div>\r\n\r\n<!-- 双语模式设置 -->\r\n<div class=\"settings-item\" id=\"bilingual-mode-group\" style=\"display: flex; justify-content: space-between; align-items: center;\">\r\n    <div style=\"flex: 1; padding-right: 10px;\">\r\n        <label style=\"margin-bottom: 2px;\">启用语言与翻译</label>\r\n        <div class=\"settings-desc\">可自动或手动指定角色输出语言、翻译语言和语音朗读内容</div>\r\n    </div>\r\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \r\n        <input type=\"checkbox\" id=\"bilingual-mode-toggle\"> \r\n        <span class=\"slider\"></span> \r\n    </label>\r\n</div>\r\n\r\n<div id=\"language-policy-settings\" style=\"display: none;\">\r\n    <div class=\"settings-item language-policy-row\">\r\n        <label for=\"language-output-mode-select\">角色输出语言</label>\r\n        <div class=\"language-policy-control\">\r\n            <select id=\"language-output-mode-select\" class=\"settings-select\">\r\n                <option value=\"auto\">自动选择</option>\r\n                <option value=\"persona\">根据角色设定并保持</option>\r\n                <option value=\"user\">跟随用户语言</option>\r\n                <option value=\"fixed\">手动指定</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div class=\"settings-item language-policy-row\" id=\"language-output-custom-row\" style=\"display: none;\">\r\n        <label for=\"language-output-input\">指定输出语言</label>\r\n        <div class=\"language-policy-control\">\r\n            <input type=\"text\" id=\"language-output-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"搜索或直接描述语言、方言\">\r\n            <div id=\"language-output-suggestions\" class=\"language-suggestions\"></div>\r\n        </div>\r\n    </div>\r\n    <div class=\"settings-item language-policy-row\">\r\n        <label for=\"language-translation-mode-select\">翻译语言</label>\r\n        <div class=\"language-policy-control\">\r\n            <select id=\"language-translation-mode-select\" class=\"settings-select\">\r\n                <option value=\"fixed\">手动指定</option>\r\n                <option value=\"interface\">跟随应用语言</option>\r\n                <option value=\"none\">不生成翻译</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div class=\"settings-item language-policy-row\" id=\"language-translation-custom-row\">\r\n        <label for=\"language-translation-input\">指定翻译语言</label>\r\n        <div class=\"language-policy-control\">\r\n            <input type=\"text\" id=\"language-translation-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"如 zh-Hans-CN 或自然语言描述\">\r\n            <div id=\"language-translation-suggestions\" class=\"language-suggestions\"></div>\r\n        </div>\r\n    </div>\r\n    <div class=\"settings-item language-policy-row\">\r\n        <label for=\"language-tts-read-mode-select\">语音朗读内容</label>\r\n        <div class=\"language-policy-control\">\r\n            <select id=\"language-tts-read-mode-select\" class=\"settings-select\">\r\n                <option value=\"source\">只朗读角色原文</option>\r\n                <option value=\"translation\">只朗读翻译</option>\r\n                <option value=\"both\">先原文后翻译</option>\r\n            </select>\r\n        </div>\r\n    </div>\r\n    <div class=\"settings-item-block\">\r\n        <button type=\"button\" id=\"language-advanced-toggle\" class=\"language-advanced-toggle\" aria-expanded=\"false\">\r\n            <span>高级语言设置</span>\r\n            <span class=\"language-expand-mark\">展开</span>\r\n        </button>\r\n    </div>\r\n    <div id=\"language-advanced-panel\" hidden>\r\n        <div class=\"settings-item language-advanced-row\">\r\n            <label for=\"language-switch-policy-select\">语言保持方式</label>\r\n            <div class=\"language-policy-control\">\r\n                <select id=\"language-switch-policy-select\" class=\"settings-select\">\r\n                    <option value=\"dynamic\">按情境自然切换</option>\r\n                    <option value=\"strict\">严格保持指定语言</option>\r\n                    <option value=\"explicit\">仅明确要求时切换</option>\r\n                    <option value=\"natural\">主体固定，允许少量夹杂</option>\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"settings-item language-advanced-row\">\r\n            <label for=\"language-translation-style-select\">翻译风格</label>\r\n            <div class=\"language-policy-control\">\r\n                <select id=\"language-translation-style-select\" class=\"settings-select\">\r\n                    <option value=\"natural\">自然口语，保留语气</option>\r\n                    <option value=\"faithful\">忠实准确</option>\r\n                    <option value=\"concise\">简洁意译</option>\r\n                    <option value=\"custom\">按自定义规则</option>\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"settings-item language-advanced-row\">\r\n            <label for=\"language-narration-mode-select\">旁白语言</label>\r\n            <div class=\"language-policy-control\">\r\n                <select id=\"language-narration-mode-select\" class=\"settings-select\">\r\n                    <option value=\"inherit\">沿用现有旁白规则</option>\r\n                    <option value=\"translation\">使用翻译语言</option>\r\n                    <option value=\"fixed\">手动指定</option>\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"settings-item language-advanced-row\" id=\"language-narration-custom-row\" style=\"display: none;\">\r\n            <label for=\"language-narration-input\">指定旁白语言</label>\r\n            <div class=\"language-policy-control\">\r\n                <input type=\"text\" id=\"language-narration-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"搜索或直接描述\">\r\n                <div id=\"language-narration-suggestions\" class=\"language-suggestions\"></div>\r\n            </div>\r\n        </div>\r\n        <div class=\"settings-item-block\">\r\n            <label for=\"language-custom-instruction\">自定义语言规则</label>\r\n            <div class=\"settings-desc\">可描述方言、时代、敬语、夹杂条件、架空语言或任何特殊表达要求。</div>\r\n            <textarea id=\"language-custom-instruction\" class=\"language-policy-textarea\" placeholder=\"例如：即使用户使用中文也保持韩语；对长辈使用敬语。\"></textarea>\r\n        </div>\r\n        <div class=\"settings-item-block\">\r\n            <label for=\"language-examples-input\">语言示例</label>\r\n            <div class=\"settings-desc\">可填写角色会怎样说、不会怎样说，以及架空词汇的固定含义。</div>\r\n            <textarea id=\"language-examples-input\" class=\"language-policy-textarea\" placeholder=\"填写原文、译文或正反示例\"></textarea>\r\n        </div>\r\n        <div class=\"settings-item-block\" id=\"language-member-overrides-group\" style=\"display: none;\">\r\n            <label>群聊成员语言覆盖</label>\r\n            <div class=\"settings-desc\">留空即沿用群聊设置；可直接输入任意语言、方言或自定义描述。</div>\r\n            <div id=\"language-member-overrides-list\" class=\"language-member-list\"></div>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- 双语模式生效角色 (仅群聊) -->\r\n<div class=\"settings-item-block\" id=\"bilingual-characters-group\" style=\"display: none;\"> \r\n    <label>语言与翻译生效角色 (仅群聊)</label>\r\n    <div class=\"settings-desc\">勾选需要应用语言与翻译规则的角色，未勾选的保持原有单语输出（如果不勾选任何角色，则等同于全员生效）。</div>\r\n    <div class=\"custom-multiselect\" style=\"margin-top: 5px; position: relative;\" id=\"bilingual-chars-multiselect\">\r\n        <div class=\"select-box\"> <span class=\"selected-options-text\">-- 点击选择 --</span> <span class=\"arrow-down\">▼</span> </div>\r\n        <div id=\"bilingual-chars-checkboxes-container\" class=\"checkboxes-container\"> </div>\r\n    </div>\r\n</div>\r\n\r\n<!-- 双语模式显示位置设置 -->\r\n<div class=\"settings-item\" id=\"bilingual-display-mode-group\" style=\"display: none;\">\r\n    <label>翻译显示位置</label>\r\n    <div class=\"settings-right\">\r\n        <select id=\"bilingual-display-mode-select\" class=\"settings-select\" style=\"width: 100%; text-align: right;\">\r\n            <option value=\"outside\">气泡外部</option>\r\n            <option value=\"inside\">气泡内部</option>\r\n        </select>\r\n    </div>\r\n</div>\r\n\r\n<div class=\"settings-item\" id=\"todo-list-setting-group\">\r\n    <div style=\"flex: 1; padding-right: 10px;\">\r\n        <label style=\"margin-bottom: 2px;\">启用待办事项同步</label>\r\n        <div class=\"settings-desc\">开启后，AI将读取【今日】及【未完成】的待办事项。</div>\r\n    </div>\r\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \r\n        <input type=\"checkbox\" id=\"enable-todo-list-switch\"> \r\n        <span class=\"slider\"></span> \r\n    </label>\r\n</div>\r\n             <!-- 表情包识图 -->\r\n             <div class=\"settings-item\" id=\"sticker-vision-group\">\r\n                 <div>\r\n                    <label>启用表情包识图</label>\r\n                    <div class=\"settings-desc\">CHAR可以看到USER表情包的内容</div>\r\n                 </div>\r\n                 <label class=\"toggle-switch\"> \r\n                    <input type=\"checkbox\" id=\"enable-sticker-vision-checkbox\"> \r\n                    <span class=\"slider\"></span> \r\n                 </label>\r\n             </div>\r\n             \r\n             <!-- 表情包智能匹配 -->\r\n             <div class=\"settings-item\" id=\"sticker-smart-match-group\">\r\n                 <div>\r\n                    <label>启用表情包智能匹配</label>\r\n                    <div class=\"settings-desc\">输入文字时自动匹配相关表情包</div>\r\n                 </div>\r\n                 <label class=\"toggle-switch\"> \r\n                    <input type=\"checkbox\" id=\"enable-sticker-smart-match-checkbox\"> \r\n                    <span class=\"slider\"></span> \r\n                 </label>\r\n             </div>\r\n             \r\n             <!-- 线下模式 -->\r\n             <div id=\"offline-mode-group\">\r\n                 <div class=\"settings-item\">\r\n                     <div>\r\n                        <label>线下模式 (描写模式)</label>\r\n                        <div class=\"settings-desc\">AI将输出包含动作/心理的描写文本</div>\r\n                     </div>\r\n                     <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"offline-mode-toggle\"> <span class=\"slider\"></span> </label>\r\n                 </div>\r\n                 <div id=\"offline-mode-options\" style=\"display: none; padding: 0 16px 16px 16px;\">\r\n                     <div style=\"display:flex; align-items:center; gap:10px; margin-bottom:10px;\">\r\n                        <span style=\"font-size:13px; color:#666;\">字数范围:</span>\r\n                        <input type=\"number\" id=\"offline-min-length-input\" class=\"settings-num-input\" value=\"100\">\r\n                        <span>-</span>\r\n                        <input type=\"number\" id=\"offline-max-length-input\" class=\"settings-num-input\" value=\"300\">\r\n                     </div>\r\n                     <label style=\"font-size:13px; color:#666;\">文风预设:</label>\r\n                     <select id=\"offline-preset-select\" class=\"settings-select\" style=\"width:100%; margin-top:5px;\"></select>\r\n                     <div style=\"display:flex; align-items:center; justify-content:space-between; margin-top:12px;\">\r\n                        <div>\r\n                           <span style=\"font-size:13px; color:#666;\">连续排版模式</span>\r\n                           <div style=\"font-size:11px; color:#999; margin-top:2px;\">对话与描写不分段，保持自然段落</div>\r\n                        </div>\r\n                        <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"offline-continuous-layout-toggle\"> <span class=\"slider\"></span> </label>\r\n                     </div>\r\n                 </div>\r\n             </div>\r\n\r\n            <!-- 时间感知 -->\r\n            <div class=\"settings-item\" id=\"time-perception-group\">\r\n                <div style=\"min-width: 0; flex: 1; padding-right: 10px;\">\r\n                    <label>时间感知</label>\r\n                    <div class=\"settings-desc time-awareness-inline-desc\">让角色感知当前时间与互动间隔</div>\r\n                </div>\r\n                <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"time-perception-toggle\"> <span class=\"slider\"></span> </label>\r\n            </div>\r\n\r\n            <div id=\"time-awareness-settings\" class=\"time-awareness-settings\" style=\"display: none;\">\r\n                <div class=\"settings-item time-awareness-compact-row\">\r\n                    <label for=\"time-awareness-preset-select\">感知方式</label>\r\n                    <select id=\"time-awareness-preset-select\" class=\"settings-select time-awareness-select\">\r\n                        <option value=\"adaptive\">角色自主（推荐）</option>\r\n                        <option value=\"subtle\">轻微</option>\r\n                        <option value=\"natural\">自然</option>\r\n                        <option value=\"strong\">强烈</option>\r\n                        <option value=\"custom\">自定义</option>\r\n                    </select>\r\n                </div>\r\n                <div id=\"time-awareness-preset-summary\" class=\"time-awareness-summary\"></div>\r\n\r\n                <button type=\"button\" id=\"time-awareness-advanced-toggle\" class=\"time-awareness-disclosure\" aria-expanded=\"false\">\r\n                    <span>高级时间感知设置</span>\r\n                    <span class=\"time-awareness-disclosure-state\">展开</span>\r\n                </button>\r\n\r\n                <div id=\"time-awareness-advanced-panel\" class=\"time-awareness-advanced-panel\" hidden>\r\n                    <div class=\"time-awareness-subtitle\">回来判定</div>\r\n                    <div class=\"settings-item time-awareness-compact-row\">\r\n                        <label for=\"time-awareness-min-gap-input\">至少离开</label>\r\n                        <div class=\"time-awareness-number-control\">\r\n                            <input type=\"number\" id=\"time-awareness-min-gap-input\" class=\"settings-num-input\" min=\"0\" max=\"525600\" step=\"1\" value=\"180\">\r\n                            <span>分钟</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"settings-item time-awareness-compact-row\">\r\n                        <label for=\"time-awareness-duration-style-select\">时长表达</label>\r\n                        <select id=\"time-awareness-duration-style-select\" class=\"settings-select time-awareness-select\">\r\n                            <option value=\"vague\">模糊自然</option>\r\n                            <option value=\"approximate\">大致时长</option>\r\n                            <option value=\"exact\">准确时长</option>\r\n                        </select>\r\n                    </div>\r\n                    <div class=\"settings-item time-awareness-compact-row\">\r\n                        <label for=\"time-awareness-frequency-select\">回应频率</label>\r\n                        <select id=\"time-awareness-frequency-select\" class=\"settings-select time-awareness-select\">\r\n                            <option value=\"autonomous\">角色自主</option>\r\n                            <option value=\"rare\">偶尔</option>\r\n                            <option value=\"moderate\">适中</option>\r\n                            <option value=\"frequent\">经常</option>\r\n                            <option value=\"always\">每次回来</option>\r\n                        </select>\r\n                    </div>\r\n                    <div id=\"time-awareness-group-options\" hidden>\r\n                        <div class=\"settings-item time-awareness-compact-row\">\r\n                            <label for=\"time-awareness-group-gap-basis\">群聊间隔依据</label>\r\n                            <select id=\"time-awareness-group-gap-basis\" class=\"settings-select time-awareness-select\">\r\n                                <option value=\"groupSilence\">群聊整体沉默</option>\r\n                                <option value=\"userAbsence\">用户未在群里发言</option>\r\n                            </select>\r\n                        </div>\r\n                        <div class=\"settings-item time-awareness-compact-row\">\r\n                            <label for=\"time-awareness-group-max-responders\">最多回应角色</label>\r\n                            <div class=\"time-awareness-number-control\">\r\n                                <input type=\"number\" id=\"time-awareness-group-max-responders\" class=\"settings-num-input\" min=\"1\" max=\"20\" step=\"1\" value=\"1\">\r\n                                <span>人</span>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"time-awareness-subtitle\">提供给角色的信息</div>\r\n                    <div class=\"time-awareness-toggle-grid\">\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-date\"> 日期与星期</label>\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-time\"> 当前时刻</label>\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-period\"> 早晚时段</label>\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-gap\"> 离开时长</label>\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-last-time\"> 上次互动时间</label>\r\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-cross-day\"> 是否跨天</label>\r\n                    </div>\r\n\r\n                    <div class=\"time-awareness-subtitle\">角色反应权限</div>\r\n                    <div class=\"time-awareness-toggle-list\">\r\n                        <label><span>允许直接提到离开时间</span><input type=\"checkbox\" id=\"time-awareness-allow-mention\"></label>\r\n                        <label><span>允许用情绪、想念、担心或不满体现</span><input type=\"checkbox\" id=\"time-awareness-allow-emotion\"></label>\r\n                        <label><span>允许询问或分享最近的事情</span><input type=\"checkbox\" id=\"time-awareness-allow-updates\"></label>\r\n                        <label><span>允许在自然时开启新话题</span><input type=\"checkbox\" id=\"time-awareness-allow-new-topic\"></label>\r\n                        <label><span>允许继续尚未结束的话题</span><input type=\"checkbox\" id=\"time-awareness-allow-continue\"></label>\r\n                        <label><span>优先回应用户当前消息</span><input type=\"checkbox\" id=\"time-awareness-prioritize-current\"></label>\r\n                        <label><span>根据角色人设和双方关系调整</span><input type=\"checkbox\" id=\"time-awareness-persona-aware\"></label>\r\n                        <label><span>离开越久，允许反应越明显</span><input type=\"checkbox\" id=\"time-awareness-scale-gap\"></label>\r\n                        <label><span>避免机械使用“好久不见”</span><input type=\"checkbox\" id=\"time-awareness-avoid-cliche\"></label>\r\n                        <label><span>只在回来后的第一轮处理时间差</span><input type=\"checkbox\" id=\"time-awareness-first-reply-only\"></label>\r\n                    </div>\r\n\r\n                    <div class=\"time-awareness-subtitle\">回来反应提示词</div>\r\n                    <div class=\"settings-item time-awareness-compact-row\">\r\n                        <label for=\"time-awareness-prompt-mode-select\">使用方式</label>\r\n                        <select id=\"time-awareness-prompt-mode-select\" class=\"settings-select time-awareness-select\">\r\n                            <option value=\"builtin\">使用内置规则</option>\r\n                            <option value=\"append\">内置规则＋我的补充</option>\r\n                            <option value=\"replace\">完全替换反应规则</option>\r\n                        </select>\r\n                    </div>\r\n                    <div id=\"time-awareness-prompt-editor\" class=\"time-awareness-prompt-editor\" hidden>\r\n                        <div class=\"time-awareness-variable-hint\">留空时自动回退内置规则。可用变量：{{当前时间}} {{时间段}} {{离开时长}} {{上次互动时间}} {{角色名}} {{用户昵称}} {{双方关系}} {{最近对话状态}}</div>\r\n                        <textarea id=\"time-awareness-custom-prompt\" class=\"time-awareness-textarea\" rows=\"7\" placeholder=\"写下角色在用户回来时应如何反应……\"></textarea>\r\n                        <div class=\"time-awareness-actions\">\r\n                            <button type=\"button\" id=\"time-awareness-reset-prompt-btn\">恢复档位默认</button>\r\n                            <button type=\"button\" id=\"time-awareness-copy-prompt-btn\">复制</button>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"time-awareness-subtitle\">模拟预览</div>\r\n                    <div class=\"time-awareness-preview-controls\">\r\n                        <select id=\"time-awareness-preview-gap\" class=\"settings-select\">\r\n                            <option value=\"10\">离开 10 分钟</option>\r\n                            <option value=\"180\">离开 3 小时</option>\r\n                            <option value=\"2880\">离开 2 天</option>\r\n                            <option value=\"43200\">离开 30 天</option>\r\n                        </select>\r\n                        <button type=\"button\" id=\"time-awareness-preview-btn\">生成预览</button>\r\n                    </div>\r\n                    <pre id=\"time-awareness-preview-output\" class=\"time-awareness-preview-output\" hidden></pre>\r\n\r\n                    <div class=\"time-awareness-subtitle\">暂停与后台</div>\r\n                    <div class=\"time-awareness-toggle-list\">\r\n                        <label><span>世界时间暂停时不累计离开时长</span><input type=\"checkbox\" id=\"time-awareness-pause-gap\"></label>\r\n                        <label><span>世界时间暂停时暂停本聊天后台活动</span><input type=\"checkbox\" id=\"time-awareness-pause-background\"></label>\r\n                        <label><span>立即暂停本聊天后台活动</span><input type=\"checkbox\" id=\"time-awareness-background-paused\"></label>\r\n                        <label><span>后台主动行动也使用自定义回来规则</span><input type=\"checkbox\" id=\"time-awareness-prompt-in-background\"></label>\r\n                    </div>\r\n\r\n                    <div class=\"time-awareness-actions time-awareness-default-actions\">\r\n                        <button type=\"button\" id=\"time-awareness-save-default-btn\">保存为全局默认</button>\r\n                        <button type=\"button\" id=\"time-awareness-load-default-btn\">载入全局默认</button>\r\n                        <button type=\"button\" id=\"time-awareness-export-btn\">导出配置</button>\r\n                        <button type=\"button\" id=\"time-awareness-import-btn\">导入配置</button>\r\n                        <input type=\"file\" id=\"time-awareness-import-file\" accept=\".json\" hidden>\r\n                        <button type=\"button\" id=\"time-awareness-apply-all-btn\">应用到全部聊天</button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 一起听时长感知 -->\r\n            <div class=\"settings-item\" id=\"music-time-awareness-group\" style=\"display: none;\">\r\n                <div style=\"flex: 1; padding-right: 10px;\">\r\n                    <label style=\"margin-bottom: 2px;\">一起听时长感知</label>\r\n                    <div class=\"settings-desc\">开启后角色可感知累计一起听歌的时长</div>\r\n                </div>\r\n                <label class=\"toggle-switch\" style=\"margin: 0;\">\r\n                    <input type=\"checkbox\" id=\"music-time-awareness-toggle\">\r\n                    <span class=\"slider\"></span>\r\n                </label>\r\n            </div>\r\n            <div class=\"settings-item-block\" id=\"time-zone-group\" style=\"display: none;\">\r\n                <label>时区设置</label>\r\n                <div style=\"margin-top: 10px; width: 100%;\">\r\n                    <input type=\"search\" id=\"time-zone-search-input\" placeholder=\"搜索时区...\" class=\"settings-textarea\" style=\"height: 36px; padding: 8px; margin-bottom: 8px;\">\r\n                    <select id=\"time-zone-select\" class=\"settings-select\" style=\"width: 100%; padding: 10px; background-color: #f5f5f7;\"></select>\r\n                </div>\r\n            </div>\r\n\r\n            <!-- 自定义时间 -->\r\n            <div class=\"settings-item\" id=\"custom-time-group\">\r\n                <label>自定义时间</label>\r\n                <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"custom-time-toggle\"> <span class=\"slider\"></span> </label>\r\n            </div>\r\n            <div class=\"settings-item-block\" id=\"custom-time-settings-group\" style=\"display: none;\">\r\n                <label>时间设置</label>\r\n                <div style=\"margin-top: 10px; width: 100%;\">\r\n                    <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px;\">\r\n                        <div>\r\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">年份</label>\r\n                            <input type=\"number\" id=\"custom-year-input\" class=\"settings-num-input\" placeholder=\"2024\" min=\"1900\" max=\"2100\" style=\"width: 100%;\">\r\n                        </div>\r\n                        <div>\r\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">月份</label>\r\n                            <input type=\"number\" id=\"custom-month-input\" class=\"settings-num-input\" placeholder=\"1-12\" min=\"1\" max=\"12\" style=\"width: 100%;\">\r\n                        </div>\r\n                    </div>\r\n                    <div style=\"display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin-bottom: 10px;\">\r\n                        <div>\r\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">日期</label>\r\n                            <input type=\"number\" id=\"custom-day-input\" class=\"settings-num-input\" placeholder=\"1-31\" min=\"1\" max=\"31\" style=\"width: 100%;\">\r\n                        </div>\r\n                        <div>\r\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">小时</label>\r\n                            <input type=\"number\" id=\"custom-hour-input\" class=\"settings-num-input\" placeholder=\"0-23\" min=\"0\" max=\"23\" style=\"width: 100%;\">\r\n                        </div>\r\n                        <div>\r\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">分钟</label>\r\n                            <input type=\"number\" id=\"custom-minute-input\" class=\"settings-num-input\" placeholder=\"0-59\" min=\"0\" max=\"59\" style=\"width: 100%;\">\r\n                        </div>\r\n                    </div>\r\n                    <div style=\"font-size: 12px; color: #999; margin-top: 5px;\">\r\n                        当前设置：<span id=\"custom-time-preview\" style=\"color: #007AFF; font-weight: 500;\">未设置</span>\r\n                    </div>\r\n                    <div class=\"time-awareness-clock-actions\">\r\n                        <button type=\"button\" id=\"custom-time-pause-btn\">暂停世界时间</button>\r\n                        <span id=\"custom-time-pause-status\">运行中</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n             \r\n             <!-- NAI设置 (单聊/群聊复用ID，JS控制) -->\r\n             <div class=\"settings-item-block\" id=\"nai-character-settings-group\" style=\"display: none;\">\r\n                <label>NAI 出图设置 (角色专属)</label>\r\n                <div style=\"margin-top: 10px;\">\r\n                    <button id=\"character-nai-prompts-btn\" class=\"settings-full-btn\">配置专属提示词</button>\r\n                </div>\r\n             </div>\r\n             <div class=\"settings-item-block\" id=\"group-nai-settings-group\" style=\"display: none;\">\r\n                <label>NAI 出图设置 (群聊专属)</label>\r\n                <div style=\"margin-top: 10px;\">\r\n                    <button id=\"group-character-nai-prompts-btn\" class=\"settings-full-btn\">配置专属提示词</button>\r\n                </div>\r\n             </div>\r\n        </div>\r\n\r\n        <!-- 第五组：外观与视觉 -->\r\n        <div class=\"settings-section\">\r\n            <div class=\"settings-item\">\r\n                 <label>聊天背景</label>\r\n                 <!-- 增加 full-width 类以保持右对齐，内部使用 avatar-btn-group 保持间距一致 -->\r\n                 <div class=\"settings-right full-width\">\r\n                     <div class=\"avatar-btn-group\" style=\"justify-content: flex-end; width: 100%;\">\r\n                         <!-- 升级为实体小按钮 -->\r\n                         <button class=\"settings-mini-btn\" onclick=\"document.getElementById('bg-input').click()\">上传</button>\r\n                         <button class=\"settings-mini-btn\" id=\"remove-bg-btn\">移除</button>\r\n                         \r\n                         <!-- 保持原有的隐藏 input 和预览图逻辑 -->\r\n                         <input type=\"file\" id=\"bg-input\" accept=\"image/*\" hidden>\r\n                         <img id=\"bg-preview\" class=\"settings-bg-preview\">\r\n                     </div>\r\n                 </div>\r\n            </div>\r\n            \r\n            <div class=\"settings-item-block\">\r\n                <label>气泡主题</label>\r\n                 <div style=\"display:flex; justify-content:space-between; margin-bottom:10px; align-items:center;\">\r\n                    <select id=\"theme-preset-select\" class=\"settings-select\" style=\"flex:1; margin-right:10px;\"></select>\r\n                    <div style=\"display:flex; gap:6px;\">\r\n                        <button id=\"save-theme-preset-btn\" class=\"settings-mini-btn\" title=\"保存预设\" style=\"padding: 4px 8px; font-size: 12px;\">保存</button>\r\n                        <button id=\"delete-theme-preset-btn\" class=\"settings-mini-btn\" title=\"删除预设\" style=\"padding: 4px 8px; font-size: 12px; color:#ff3b30;\">删除</button>\r\n                    </div>\r\n                 </div>\r\n                 <!-- 补全所有主题选项 -->\r\n                 <div class=\"theme-selector\" id=\"theme-selector-container\" style=\"max-height: 120px; overflow-y: auto; display: flex; flex-wrap: wrap; gap: 12px; padding: 5px 0;\">\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"default\" id=\"theme-default\"> 默认</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_blue\"> 粉蓝</label> \r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_white\"> 蓝白</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"purple_yellow\"> 紫黄</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"black_white\"> 黑白</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"yellow_white\"> 黄白</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"red_black\"> 红黑</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_yellow\"> 蓝黄</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_yellow\"> 粉黄</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_purple\"> 粉紫</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"gray_white\"> 灰白</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_green\"> 蓝绿</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_white\"> 粉白</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_black\"> 粉黑</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_green\"> 粉绿</label>\r\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"green_black\"> 绿黑</label>\r\n                      \r\n                      <!-- 动态渲染的自定义预设将插入在这里 -->\r\n                      \r\n                      <button id=\"reset-theme-btn\" class=\"settings-text-btn\" style=\"margin-left: auto;\">重置默认</button>\r\n                 </div>\r\n                 \r\n                 <!-- 新增：自定义气泡颜色功能区 -->\r\n                 <div style=\"margin-top: 10px; padding-top: 10px; border-top: 1px dashed rgba(0,0,0,0.1);\">\r\n                     <div style=\"display: flex; gap: 10px; align-items: center; margin-bottom: 8px;\">\r\n                         <label style=\"font-size: 13px; color: var(--text-secondary);\">我的气泡</label>\r\n                         <input type=\"color\" id=\"custom-user-bubble-color\" value=\"#fff0f6\" style=\"width: 30px; height: 30px; padding: 0; border: none; cursor: pointer;\">\r\n                         <label style=\"font-size: 13px; color: var(--text-secondary); margin-left: 10px;\">对方气泡</label>\r\n                         <input type=\"color\" id=\"custom-ai-bubble-color\" value=\"#eff7ff\" style=\"width: 30px; height: 30px; padding: 0; border: none; cursor: pointer;\">\r\n                     </div>\r\n                     <div style=\"display: flex; flex-direction: column; gap: 8px;\">\r\n                         <input type=\"text\" id=\"custom-theme-name\" placeholder=\"自定义颜色名称...\" style=\"width: 100%; box-sizing: border-box; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; font-size: 14px;\">\r\n                         <div style=\"display: flex; gap: 8px; justify-content: flex-end;\">\r\n                             <button id=\"add-custom-theme-btn\" class=\"settings-mini-btn\" style=\"background-color: var(--accent-color); color: white;\">保存预设</button>\r\n                             <button id=\"manage-custom-themes-btn\" class=\"settings-mini-btn\">管理</button>\r\n                         </div>\r\n                     </div>\r\n                 </div>\r\n            </div>\r\n\r\n            <div class=\"settings-item\">\r\n                 <label>字体大小 <span id=\"chat-font-size-value\" style=\"color:#888; font-size:12px;\">13px</span></label>\r\n                 <div class=\"settings-right\" style=\"width: 50%;\">\r\n                    <input type=\"range\" id=\"chat-font-size-slider\" min=\"12\" max=\"20\" step=\"1\" style=\"width:100%;\">\r\n                 </div>\r\n            </div>\r\n            \r\n            <div class=\"settings-item-block\">\r\n                 <label style=\"display: flex; justify-content: space-between; align-items: center;\">\r\n                     <div style=\"display: flex; align-items: center; gap: 5px;\">\r\n                         自定义 CSS\r\n                         <button type=\"button\" onclick=\"openFullscreenEditor('custom-css-input', '当前聊天自定义 CSS')\" title=\"放大编辑\" style=\"background: none; border: none; cursor: pointer; color: #888; padding: 4px; display: flex; align-items: center; justify-content: center;\">\r\n                             <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7\"/></svg>\r\n                         </button>\r\n                     </div>\r\n                     <button id=\"reset-custom-css-btn\" style=\"font-size:12px;\">重置</button>\r\n                 </label>\r\n                 <textarea id=\"custom-css-input\" rows=\"3\" class=\"settings-textarea\" placeholder=\"/* 针对当前聊天的CSS */\"></textarea>\r\n            </div>\r\n\r\n            <div class=\"settings-item-block\">\r\n                <label>效果预览</label>\r\n                <div id=\"settings-preview-area\" style=\"margin-top:10px;\"></div>\r\n            </div>\r\n            \r\n            <div class=\"settings-item-block\" id=\"lyrics-position-group\" style=\"display: none;\">\r\n                 <label>歌词栏设置</label>\r\n                 <div style=\"display:flex; gap:10px; margin-top:10px;\">\r\n                     <select id=\"lyrics-vertical-pos\" class=\"settings-select\"><option value=\"top\">顶部</option><option value=\"bottom\">底部</option></select>\r\n                     <select id=\"lyrics-horizontal-pos\" class=\"settings-select\"><option value=\"center\">居中</option><option value=\"left\">居左</option><option value=\"right\">居右</option></select>\r\n                     <input type=\"number\" id=\"lyrics-offset-input\" class=\"settings-num-input\" value=\"10\" placeholder=\"偏移\">\r\n                 </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- 第六组：数据与操作 (底部) -->\r\n        <div class=\"settings-section\">\r\n             <div class=\"settings-item clickable\" id=\"search-history-btn\">\r\n                 <label>查找聊天记录</label>\r\n                 <div class=\"settings-right\">›</div>\r\n             </div>\r\n             \r\n             <div class=\"settings-item clickable\" id=\"export-single-chat-btn\">\r\n                 <label>导出聊天记录</label>\r\n                 <div class=\"settings-right\">›</div>\r\n             </div>\r\n             \r\n             <div class=\"settings-item clickable\" id=\"import-single-chat-btn\">\r\n                 <label>导入聊天记录</label>\r\n                 <div class=\"settings-right\">\r\n                     ›\r\n                     <input type=\"file\" id=\"import-single-chat-input\" accept=\"application/json\" hidden>\r\n                 </div>\r\n             </div>\r\n\r\n             <div class=\"settings-item clickable\" id=\"export-character-full-btn\">\r\n                 <label>导出角色</label>\r\n                 <div class=\"settings-right\">›</div>\r\n             </div>\r\n\r\n             <div class=\"settings-item clickable\" id=\"clear-chat-btn\">\r\n                 <label style=\"color: #ff3b30;\">清空聊天记录</label>\r\n                 <div class=\"settings-right\">›</div>\r\n             </div>\r\n             \r\n             <div class=\"settings-item clickable\" id=\"block-chat-btn\">\r\n                 <label style=\"color: #ff3b30;\">拉黑对方 / 移出群聊</label>\r\n                 <div class=\"settings-right\">›</div>\r\n             </div>\r\n        </div>\r\n        \r\n        <div style=\"height: 40px;\"></div> <!-- 底部垫高 -->\r\n      </div>\r\n    </div>\r\n    <div id=\"rendering-rules-screen\" class=\"screen\">\r\n      <div class=\"header\"> \r\n        <span class=\"back-btn\" onclick=\"showScreen('home-screen')\">‹</span> \r\n        <span data-lang-key=\"homeAppRenderer\">渲染规则</span> \r\n        <div class=\"header-actions\">\r\n            <div class=\"rules-more-wrapper\">\r\n                <span class=\"action-btn\" id=\"rules-more-btn\" title=\"更多操作\" aria-haspopup=\"true\" aria-expanded=\"false\">\r\n                    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                        <circle cx=\"12\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\r\n                        <circle cx=\"19\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\r\n                        <circle cx=\"5\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\r\n                    </svg>\r\n                </span>\r\n                <div class=\"rules-dropdown-menu\" id=\"rules-more-menu\" style=\"display: none;\">\r\n                    <button type=\"button\" class=\"rules-dropdown-item\" id=\"import-rules-btn\">\r\n                        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"7 10 12 15 17 10\"></polyline><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line></svg>\r\n                        <span>导入规则</span>\r\n                    </button>\r\n                    <button type=\"button\" class=\"rules-dropdown-item\" id=\"manage-rules-btn\">\r\n                        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                            <path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"></path>\r\n                            <polyline points=\"9 11 12 14 22 4\"></polyline>\r\n                        </svg>\r\n                        <span id=\"manage-rules-btn-text\">批量管理</span>\r\n                    </button>\r\n                </div>\r\n            </div>\r\n            <span class=\"action-btn\" id=\"rules-exit-manage-btn\" title=\"完成管理\" style=\"display: none;\">\r\n                <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\r\n                    <polyline points=\"20 6 9 17 4 12\"></polyline>\r\n                </svg>\r\n            </span>\r\n            <span class=\"action-btn\" id=\"add-new-rule-btn\" title=\"创建新规则\">+</span> \r\n        </div>\r\n      </div>\r\n      <div id=\"rules-tabs\"> </div>\r\n      <div id=\"rules-content-container\" class=\"list-container\"> </div>\r\n      \r\n      <div id=\"rules-action-bar\" style=\"display: none; position: absolute; bottom: 0; left: 0; width: 100%; padding: 15px 20px; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); border-top: 1px solid #eee; box-sizing: border-box; justify-content: space-between; align-items: center; z-index: 10;\">\r\n          <label style=\"display:flex; align-items:center; gap:5px; font-size:16px;\">\r\n              <input type=\"checkbox\" id=\"select-all-rules-checkbox\"> 全选\r\n          </label>\r\n          <div style=\"display:flex; gap:10px;\">\r\n              <button id=\"export-selected-rules-btn\" class=\"settings-mini-btn\" style=\"background-color: #007aff; color: white; border: none;\">导出 (0)</button>\r\n              <button id=\"delete-selected-rules-btn\" class=\"settings-mini-btn\" style=\"color: #ff3b30;\">删除 (0)</button>\r\n          </div>\r\n      </div>\r\n    </div>\r\n    <input type=\"file\" id=\"import-rules-input\" accept=\".json\" style=\"display: none;\">\r\n    <div id=\"rule-editor-modal\" class=\"modal\">\r\n      <div class=\"modal-content\" style=\"height: 85%;\">\r\n        <div class=\"modal-header\"> <span id=\"rule-editor-title\">创建新规则</span> </div>\r\n        <div class=\"modal-body\" style=\"display: flex; flex-direction: column; gap: 15px;\">\r\n          <div class=\"form-group\" style=\"flex-shrink: 0;\"> <label for=\"rule-name-input\">规则名称</label> <input type=\"text\" id=\"rule-name-input\" placeholder=\"例如：美团外卖卡片\"> </div>\r\n          <div class=\"form-group\" style=\"flex-shrink: 0;\"> <label for=\"rule-chat-id-select\">绑定范围</label> <select id=\"rule-chat-id-select\">\r\n              <option value=\"global\">公用 (所有角色)</option>\r\n            </select> </div>\r\n          <div class=\"form-group\" style=\"flex-grow: 1; display: flex; flex-direction: column;\"> <label for=\"rule-regex-input\">正则表达式 (使用g作为标志)</label> <textarea id=\"rule-regex-input\" rows=\"3\" style=\"font-family: monospace; resize: vertical;\" placeholder=\"例如：MTR\\[(.*?)\\]\\[(.*?)\\|(.*?)\\]\"></textarea>\r\n          </div>\r\n          <div class=\"form-group\" style=\"flex-grow: 2; display: flex; flex-direction: column;\"> <label for=\"rule-template-input\">HTML 模板 (用 $1, $2 引用)</label> <textarea id=\"rule-template-input\" rows=\"6\" style=\"font-family: monospace; resize: vertical;\"\r\n              placeholder=\"例如：<div class=`waimai-card`>...<span>$2</span>...</div>\"></textarea> </div>\r\n          <div class=\"form-group\" style=\"display: flex; justify-content: space-between; align-items: center; flex-shrink: 0;\"> <label for=\"rule-enabled-switch\" style=\"margin-bottom: 0;\">启用规则</label> <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"rule-enabled-switch\" checked>\r\n              <span class=\"slider\"></span> </label> </div>\r\n<div class=\"form-group\" style=\"display: flex; justify-content: space-between; align-items: center; flex-shrink: 0;\">\r\n    <label for=\"rule-do-not-send-switch\" style=\"margin-bottom: 0;\">\r\n        渲染时从上下文中删除\r\n        <p style=\"font-size: 12px; font-weight: normal; color: #999; margin-top: 5px;\">\r\n            开启后，匹配此规则的消息将不会被发送给AI，仅用于前端显示。\r\n        </p>\r\n    </label>\r\n    <label class=\"toggle-switch\">\r\n        <input type=\"checkbox\" id=\"rule-do-not-send-switch\">\r\n        <span class=\"slider\"></span>\r\n    </label>\r\n</div>\r\n        </div>\r\n        <div class=\"modal-footer\"> <button class=\"cancel\" id=\"cancel-rule-editor-btn\" data-lang-key=\"cancel\">取消</button> <button class=\"save\" id=\"save-rule-btn\"data-lang-key=\"save\">保存规则</button> </div>\r\n      </div>\r\n    </div>\r\n";
